export type ColumnId = 'todo' | 'doing' | 'done'
export type Priority = 'low' | 'medium' | 'high'

export interface Card {
  id: string
  title: string
  description: string
  /** ISO date `YYYY-MM-DD`, or empty string when there is no due date. */
  due: string
  priority: Priority
  column: ColumnId
}

export type CardInput = Pick<Card, 'title' | 'description' | 'due' | 'priority'>

export const COLUMNS: { id: ColumnId; title: string }[] = [
  { id: 'todo', title: 'To do' },
  { id: 'doing', title: 'Doing' },
  { id: 'done', title: 'Done' },
]

export const PRIORITIES: { id: Priority; label: string }[] = [
  { id: 'low', label: 'Low' },
  { id: 'medium', label: 'Medium' },
  { id: 'high', label: 'High' },
]

export const WIP_LIMIT = 3
export const STORAGE_KEY = 'kanban-board-v1'

const COLUMN_IDS = COLUMNS.map((c) => c.id)
const PRIORITY_IDS = PRIORITIES.map((p) => p.id)
const DATE_RE = /^\d{4}-\d{2}-\d{2}$/

export function newId(): string {
  if (typeof crypto !== 'undefined' && 'randomUUID' in crypto) return crypto.randomUUID()
  return Math.random().toString(36).slice(2) + Date.now().toString(36)
}

/** Local calendar date as `YYYY-MM-DD` (not UTC, so "today" matches the user's clock). */
export function todayISO(now: Date = new Date()): string {
  const y = now.getFullYear()
  const m = String(now.getMonth() + 1).padStart(2, '0')
  const d = String(now.getDate()).padStart(2, '0')
  return `${y}-${m}-${d}`
}

export function cardsIn(cards: Card[], column: ColumnId): Card[] {
  return cards.filter((c) => c.column === column)
}

export function addCard(cards: Card[], input: CardInput, column: ColumnId = 'todo', id: string = newId()): Card[] {
  const card: Card = { id, column, ...normalizeInput(input) }
  return [...cards, card]
}

export function updateCard(cards: Card[], id: string, input: CardInput): Card[] {
  return cards.map((c) => (c.id === id ? { ...c, ...normalizeInput(input) } : c))
}

export function deleteCard(cards: Card[], id: string): Card[] {
  return cards.filter((c) => c.id !== id)
}

function normalizeInput(input: CardInput): CardInput {
  return {
    title: input.title.trim(),
    description: input.description.trim(),
    due: DATE_RE.test(input.due) ? input.due : '',
    priority: PRIORITY_IDS.includes(input.priority) ? input.priority : 'medium',
  }
}

/**
 * Move a card to `toColumn`, placing it immediately before the card `beforeId`
 * (or at the end of the column when `beforeId` is null). Using a neighbour id
 * instead of an index keeps drops correct while the board is filtered.
 */
export function moveCard(cards: Card[], id: string, toColumn: ColumnId, beforeId: string | null): Card[] {
  const card = cards.find((c) => c.id === id)
  if (!card || beforeId === id) return cards
  const rest = cards.filter((c) => c.id !== id)
  const moved = { ...card, column: toColumn }
  let insertAt: number
  const before = beforeId ? rest.findIndex((c) => c.id === beforeId && c.column === toColumn) : -1
  if (before >= 0) {
    insertAt = before
  } else {
    // After the last card of the target column (or at the end of the list).
    let last = -1
    rest.forEach((c, i) => {
      if (c.column === toColumn) last = i
    })
    insertAt = last >= 0 ? last + 1 : rest.length
  }
  return [...rest.slice(0, insertAt), moved, ...rest.slice(insertAt)]
}

/** Move a card one column left (-1) or right (+1), appending it to the end. */
export function shiftColumn(cards: Card[], id: string, dir: -1 | 1): Card[] {
  const card = cards.find((c) => c.id === id)
  if (!card) return cards
  const idx = COLUMN_IDS.indexOf(card.column) + dir
  if (idx < 0 || idx >= COLUMN_IDS.length) return cards
  return moveCard(cards, id, COLUMN_IDS[idx], null)
}

/** Move a card one position up (-1) or down (+1) within its column. */
export function shiftWithinColumn(cards: Card[], id: string, dir: -1 | 1): Card[] {
  const card = cards.find((c) => c.id === id)
  if (!card) return cards
  const col = cardsIn(cards, card.column)
  const pos = col.findIndex((c) => c.id === id)
  const target = pos + dir
  if (target < 0 || target >= col.length) return cards
  // Moving down by one = insert before the card two positions later.
  const beforeId = dir === -1 ? col[target].id : (col[target + 1]?.id ?? null)
  return moveCard(cards, id, card.column, beforeId)
}

export function isOverdue(card: Card, today: string = todayISO()): boolean {
  return card.column !== 'done' && card.due !== '' && card.due < today
}

export function isWipExceeded(cards: Card[]): boolean {
  return cardsIn(cards, 'doing').length > WIP_LIMIT
}

export interface Filter {
  query: string
  priority: Priority | 'all'
}

export function matchesFilter(card: Card, filter: Filter): boolean {
  if (filter.priority !== 'all' && card.priority !== filter.priority) return false
  const q = filter.query.trim().toLowerCase()
  if (!q) return true
  return card.title.toLowerCase().includes(q) || card.description.toLowerCase().includes(q)
}

export function isFilterActive(filter: Filter): boolean {
  return filter.query.trim() !== '' || filter.priority !== 'all'
}

/** Parse stored JSON defensively: drop anything that is not a valid card. */
export function parseBoard(raw: string | null): Card[] {
  if (!raw) return []
  let data: unknown
  try {
    data = JSON.parse(raw)
  } catch {
    return []
  }
  const list = Array.isArray(data) ? data : (data as { cards?: unknown })?.cards
  if (!Array.isArray(list)) return []
  const seen = new Set<string>()
  const out: Card[] = []
  for (const item of list) {
    if (!item || typeof item !== 'object') continue
    const c = item as Record<string, unknown>
    if (typeof c.id !== 'string' || seen.has(c.id)) continue
    if (typeof c.title !== 'string' || !c.title.trim()) continue
    if (!COLUMN_IDS.includes(c.column as ColumnId)) continue
    seen.add(c.id)
    out.push({
      id: c.id,
      title: c.title,
      description: typeof c.description === 'string' ? c.description : '',
      due: typeof c.due === 'string' && DATE_RE.test(c.due) ? c.due : '',
      priority: PRIORITY_IDS.includes(c.priority as Priority) ? (c.priority as Priority) : 'medium',
      column: c.column as ColumnId,
    })
  }
  return out
}

export function serializeBoard(cards: Card[]): string {
  return JSON.stringify({ version: 1, cards })
}

export function loadBoard(storage: Pick<Storage, 'getItem'> = localStorage): Card[] {
  try {
    return parseBoard(storage.getItem(STORAGE_KEY))
  } catch {
    return []
  }
}

export function saveBoard(cards: Card[], storage: Pick<Storage, 'setItem'> = localStorage): boolean {
  try {
    storage.setItem(STORAGE_KEY, serializeBoard(cards))
    return true
  } catch {
    return false
  }
}

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import {
  addCard,
  type Card,
  type CardInput,
  type ColumnId,
  COLUMNS,
  deleteCard,
  type Filter,
  isFilterActive,
  isOverdue,
  isWipExceeded,
  loadBoard,
  matchesFilter,
  moveCard,
  PRIORITIES,
  type Priority,
  saveBoard,
  shiftColumn,
  shiftWithinColumn,
  STORAGE_KEY,
  todayISO,
  updateCard,
  WIP_LIMIT,
} from './board'
import { CardDialog, ConfirmDialog } from './Dialogs'
import { type DragView, useCardDrag } from './useCardDrag'

const EMPTY_INPUT: CardInput = { title: '', description: '', due: '', priority: 'medium' }
const columnTitle = (id: ColumnId) => COLUMNS.find((c) => c.id === id)!.title

const PRIORITY_STYLE: Record<Priority, string> = {
  low: 'bg-emerald-100 text-emerald-800 ring-emerald-600/20',
  medium: 'bg-amber-100 text-amber-800 ring-amber-600/20',
  high: 'bg-rose-100 text-rose-800 ring-rose-600/20',
}

function formatDate(iso: string) {
  const [y, m, d] = iso.split('-').map(Number)
  return new Date(y, m - 1, d).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' })
}

type Editing = { mode: 'add'; column: ColumnId } | { mode: 'edit'; id: string } | null

export default function App() {
  const [cards, setCards] = useState<Card[]>(() => loadBoard())
  const [filter, setFilter] = useState<Filter>({ query: '', priority: 'all' })
  const [editing, setEditing] = useState<Editing>(null)
  const [deletingId, setDeletingId] = useState<string | null>(null)
  const [announcement, setAnnouncement] = useState('')
  const [today, setToday] = useState(todayISO)
  const focusAfterRender = useRef<string | null>(null)

  // Persist on every change.
  useEffect(() => {
    saveBoard(cards)
  }, [cards])

  // Keep other tabs in sync, and roll "today" over at midnight.
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY) setCards(loadBoard())
    }
    const timer = setInterval(() => setToday(todayISO()), 60_000)
    window.addEventListener('storage', onStorage)
    return () => {
      window.removeEventListener('storage', onStorage)
      clearInterval(timer)
    }
  }, [])

  // Return focus to a card after a keyboard move (it re-mounts in another column).
  useLayoutEffect(() => {
    const id = focusAfterRender.current
    if (!id) return
    focusAfterRender.current = null
    document.querySelector<HTMLElement>(`[data-card-id="${CSS.escape(id)}"]`)?.focus()
  })

  const describePosition = useCallback((list: Card[], id: string) => {
    const card = list.find((c) => c.id === id)
    if (!card) return ''
    const col = list.filter((c) => c.column === card.column)
    return `“${card.title}” moved to ${columnTitle(card.column)}, position ${col.findIndex((c) => c.id === id) + 1} of ${col.length}.`
  }, [])

  const applyMove = useCallback((next: Card[], id: string, refocus: boolean) => {
    setCards(next)
    setAnnouncement(describePosition(next, id))
    if (refocus) focusAfterRender.current = id
  }, [describePosition])

  const { drag, startDrag, suppressClick } = useCardDrag((id, target) => {
    applyMove(moveCard(cards, id, target.column, target.beforeId), id, false)
  })

  const filterActive = isFilterActive(filter)
  const visible = useMemo(() => cards.filter((c) => matchesFilter(c, filter)), [cards, filter])
  const wipExceeded = isWipExceeded(cards)
  const editingCard = editing?.mode === 'edit' ? cards.find((c) => c.id === editing.id) : undefined
  const deletingCard = deletingId ? cards.find((c) => c.id === deletingId) : undefined
  const draggedCard = drag ? cards.find((c) => c.id === drag.id) : undefined

  const handleSave = (input: CardInput) => {
    if (editing?.mode === 'add') {
      const next = addCard(cards, input, editing.column)
      setCards(next)
      setAnnouncement(`Added “${input.title.trim()}” to ${columnTitle(editing.column)}.`)
    } else if (editing?.mode === 'edit') {
      setCards(updateCard(cards, editing.id, input))
      setAnnouncement(`Saved “${input.title.trim()}”.`)
    }
    setEditing(null)
  }

  const handleCardKey = (e: React.KeyboardEvent, card: Card) => {
    if (e.target !== e.currentTarget || !e.shiftKey || e.altKey || e.ctrlKey || e.metaKey) return
    const moves: Record<string, () => Card[]> = {
      ArrowLeft: () => shiftColumn(cards, card.id, -1),
      ArrowRight: () => shiftColumn(cards, card.id, 1),
      ArrowUp: () => shiftWithinColumn(cards, card.id, -1),
      ArrowDown: () => shiftWithinColumn(cards, card.id, 1),
    }
    const fn = moves[e.key]
    if (!fn) return
    e.preventDefault()
    const next = fn()
    if (next !== cards) applyMove(next, card.id, true)
  }

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900">
      <header className="border-b border-slate-200 bg-white">
        <div className="mx-auto flex max-w-7xl flex-wrap items-center gap-3 px-4 py-3">
          <h1 className="mr-auto text-xl font-bold tracking-tight">My Kanban</h1>
          <button
            type="button"
            onClick={() => setEditing({ mode: 'add', column: 'todo' })}
            className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white shadow-sm hover:bg-indigo-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600"
          >
            + Add card
          </button>
          <div role="search" className="flex w-full flex-wrap gap-2 sm:w-auto">
            <label className="sr-only" htmlFor="search">Search cards</label>
            <input
              id="search"
              type="search"
              placeholder="Search title or description…"
              value={filter.query}
              onChange={(e) => setFilter((f) => ({ ...f, query: e.target.value }))}
              className="min-w-0 flex-1 rounded-md border border-slate-300 px-3 py-2 text-base sm:w-64 sm:flex-none sm:text-sm"
            />
            <label className="sr-only" htmlFor="priority-filter">Filter by priority</label>
            <select
              id="priority-filter"
              value={filter.priority}
              onChange={(e) => setFilter((f) => ({ ...f, priority: e.target.value as Filter['priority'] }))}
              className="rounded-md border border-slate-300 bg-white px-2 py-2 text-base sm:text-sm"
            >
              <option value="all">All priorities</option>
              {PRIORITIES.map((p) => <option key={p.id} value={p.id}>{p.label}</option>)}
            </select>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 py-4">
        <p className="mb-3 hidden text-xs text-slate-500 md:block">
          Tip: drag cards to move them, or focus a card and press <kbd className="rounded border bg-white px-1">Shift</kbd> + arrow keys.
        </p>

        {filterActive && visible.length === 0 && (
          <div role="status" className="mb-4 flex flex-wrap items-center justify-between gap-2 rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm">
            <span>No cards match your search{filter.priority !== 'all' ? ' and priority filter' : ''}.</span>
            <button type="button" onClick={() => setFilter({ query: '', priority: 'all' })} className="font-medium text-indigo-700 hover:underline">
              Clear filters
            </button>
          </div>
        )}

        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          {COLUMNS.map((col) => {
            const all = cards.filter((c) => c.column === col.id)
            const shown = visible.filter((c) => c.column === col.id)
            const isDoing = col.id === 'doing'
            const warn = isDoing && wipExceeded
            const isTarget = drag?.target?.column === col.id
            return (
              <section
                key={col.id}
                data-column={col.id}
                aria-labelledby={`col-${col.id}`}
                className={`flex flex-col rounded-xl border p-3 transition-colors ${
                  warn ? 'border-amber-400 bg-amber-50' : 'border-slate-200 bg-slate-200/60'
                } ${isTarget ? 'ring-2 ring-indigo-400' : ''}`}
              >
                <div className="mb-3 flex items-center gap-2">
                  <h2 id={`col-${col.id}`} className="font-semibold">{col.title}</h2>
                  <span
                    data-testid={`count-${col.id}`}
                    aria-label={filterActive ? `${shown.length} of ${all.length} cards shown` : `${all.length} cards`}
                    className={`rounded-full px-2 py-0.5 text-xs font-semibold ${warn ? 'bg-amber-500 text-white' : 'bg-white text-slate-700'}`}
                  >
                    {filterActive ? `${shown.length}/${all.length}` : all.length}
                    {isDoing && !filterActive && <span className="font-normal"> / {WIP_LIMIT}</span>}
                  </span>
                  <button
                    type="button"
                    onClick={() => setEditing({ mode: 'add', column: col.id })}
                    aria-label={`Add card to ${col.title}`}
                    className="ml-auto grid size-8 place-items-center rounded-md text-lg text-slate-600 hover:bg-white"
                  >
                    +
                  </button>
                </div>

                {warn && (
                  <p role="alert" className="mb-3 rounded-md bg-amber-100 px-3 py-2 text-sm text-amber-900">
                    ⚠ Work-in-progress limit exceeded: {all.length} cards in Doing (limit {WIP_LIMIT}).
                  </p>
                )}

                <ol className="flex min-h-24 flex-1 flex-col gap-2" aria-label={`${col.title} cards`}>
                  {shown.map((card) => (
                    <li key={card.id} className="contents">
                      {isTarget && drag?.target?.beforeId === card.id && <DropLine />}
                      <CardItem
                        card={card}
                        overdue={isOverdue(card, today)}
                        dragging={drag?.id === card.id}
                        onPointerDown={(e) => startDrag(e, card.id)}
                        onKeyDown={(e) => handleCardKey(e, card)}
                        onEdit={() => !suppressClick.current && setEditing({ mode: 'edit', id: card.id })}
                        onDelete={() => !suppressClick.current && setDeletingId(card.id)}
                        onMoveTo={(to) => applyMove(moveCard(cards, card.id, to, null), card.id, true)}
                      />
                    </li>
                  ))}
                  {isTarget && drag?.target?.beforeId === null && <DropLine />}
                  {shown.length === 0 && (
                    <li className="grid flex-1 place-items-center rounded-lg border-2 border-dashed border-slate-300 px-3 py-6 text-center text-sm text-slate-500">
                      {all.length > 0 ? 'No matching cards' : col.id === 'todo' ? 'Nothing to do yet — add a card' : col.id === 'doing' ? 'Nothing in progress' : 'Nothing done yet'}
                    </li>
                  )}
                </ol>
              </section>
            )
          })}
        </div>
      </main>

      {drag && draggedCard && <DragGhost drag={drag} card={draggedCard} overdue={isOverdue(draggedCard, today)} />}

      <div aria-live="polite" className="sr-only">{announcement}</div>

      <CardDialog
        open={editing !== null && (editing.mode === 'add' || !!editingCard)}
        mode={editing?.mode ?? 'add'}
        initial={editingCard ?? EMPTY_INPUT}
        onSave={handleSave}
        onClose={() => setEditing(null)}
      />
      <ConfirmDialog
        open={!!deletingCard}
        cardTitle={deletingCard?.title ?? ''}
        onClose={() => setDeletingId(null)}
        onConfirm={() => {
          if (deletingCard) {
            setCards(deleteCard(cards, deletingCard.id))
            setAnnouncement(`Deleted “${deletingCard.title}”.`)
          }
          setDeletingId(null)
        }}
      />
    </div>
  )
}

function DropLine() {
  return <div aria-hidden className="h-1 shrink-0 rounded-full bg-indigo-500" data-testid="drop-indicator" />
}

function CardBody({ card, overdue }: { card: Card; overdue: boolean }) {
  return (
    <>
      <div className="flex flex-wrap items-center gap-1.5">
        <span className={`rounded px-1.5 py-0.5 text-xs font-semibold ring-1 ring-inset ${PRIORITY_STYLE[card.priority]}`}>
          {PRIORITIES.find((p) => p.id === card.priority)!.label}
        </span>
        {overdue && <span className="rounded bg-red-600 px-1.5 py-0.5 text-xs font-semibold text-white">Overdue</span>}
      </div>
      <h3 className="mt-1.5 font-medium break-words">{card.title}</h3>
      {card.description && <p className="mt-1 text-sm whitespace-pre-line break-words text-slate-600 line-clamp-4">{card.description}</p>}
      {card.due && (
        <p className={`mt-1.5 text-xs ${overdue ? 'font-semibold text-red-700' : 'text-slate-500'}`}>
          Due <time dateTime={card.due}>{formatDate(card.due)}</time>
        </p>
      )}
    </>
  )
}

function CardItem({ card, overdue, dragging, onPointerDown, onKeyDown, onEdit, onDelete, onMoveTo }: {
  card: Card
  overdue: boolean
  dragging: boolean
  onPointerDown: (e: React.PointerEvent<HTMLElement>) => void
  onKeyDown: (e: React.KeyboardEvent) => void
  onEdit: () => void
  onDelete: () => void
  onMoveTo: (column: ColumnId) => void
}) {
  return (
    <article
      data-card-id={card.id}
      data-overdue={overdue || undefined}
      tabIndex={0}
      aria-label={`${card.title}, ${card.priority} priority${overdue ? ', overdue' : ''}`}
      aria-keyshortcuts="Shift+ArrowLeft Shift+ArrowRight Shift+ArrowUp Shift+ArrowDown"
      onPointerDown={onPointerDown}
      onKeyDown={onKeyDown}
      className={`group relative overflow-hidden rounded-lg border p-3 pl-8 shadow-sm select-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600 md:cursor-grab ${
        overdue ? 'border-red-300 bg-red-50' : 'border-slate-200 bg-white'
      } ${dragging ? 'opacity-40' : ''}`}
    >
      {overdue && <span aria-hidden className="absolute inset-y-0 left-0 w-1 bg-red-500" />}
      <span
        data-drag-handle
        aria-hidden
        title="Drag to move"
        className="absolute inset-y-0 left-0 flex w-7 cursor-grab touch-none items-center justify-center text-slate-400"
      >
        <svg width="12" height="20" viewBox="0 0 12 20" fill="currentColor">
          {[3, 10, 17].flatMap((y) => [<circle key={`a${y}`} cx="3" cy={y} r="1.6" />, <circle key={`b${y}`} cx="9" cy={y} r="1.6" />])}
        </svg>
      </span>
      <CardBody card={card} overdue={overdue} />
      <div className="mt-2 flex items-center gap-1 border-t border-slate-100 pt-2">
        <label className="sr-only" htmlFor={`move-${card.id}`}>Move “{card.title}” to column</label>
        <select
          id={`move-${card.id}`}
          value={card.column}
          onChange={(e) => onMoveTo(e.target.value as ColumnId)}
          className="mr-auto min-h-9 rounded border border-slate-200 bg-white px-1.5 text-sm text-slate-700 md:min-h-7 md:text-xs"
        >
          {COLUMNS.map((c) => <option key={c.id} value={c.id}>{c.id === card.column ? `In: ${c.title}` : `Move to ${c.title}`}</option>)}
        </select>
        <button type="button" onClick={onEdit} aria-label={`Edit “${card.title}”`} className="min-h-9 rounded px-3 text-sm font-medium text-slate-600 hover:bg-slate-100 md:min-h-7 md:px-2 md:text-xs">
          Edit
        </button>
        <button type="button" onClick={onDelete} aria-label={`Delete “${card.title}”`} className="min-h-9 rounded px-3 text-sm font-medium text-red-600 hover:bg-red-50 md:min-h-7 md:px-2 md:text-xs">
          Delete
        </button>
      </div>
    </article>
  )
}

function DragGhost({ drag, card, overdue }: { drag: DragView; card: Card; overdue: boolean }) {
  return (
    <div
      aria-hidden
      className={`pointer-events-none fixed top-0 left-0 z-50 rotate-2 rounded-lg border p-3 pl-8 shadow-xl ${overdue ? 'border-red-300 bg-red-50' : 'border-slate-200 bg-white'}`}
      style={{ width: drag.width, transform: `translate(${drag.x - drag.offsetX}px, ${drag.y - drag.offsetY}px) rotate(2deg)` }}
    >
      <CardBody card={card} overdue={overdue} />
    </div>
  )
}

import { useCallback, useEffect, useLayoutEffect, useMemo, useRef, useState } from 'react'
import {
  addCard,
  type Card,
  type CardInput,
  type ColumnId,
  COLUMNS,
  deleteCard,
  type Filter,
  isFilterActive,
  isOverdue,
  isWipExceeded,
  loadBoard,
  matchesFilter,
  moveCard,
  PRIORITIES,
  type Priority,
  saveBoard,
  shiftColumn,
  shiftWithinColumn,
  STORAGE_KEY,
  todayISO,
  updateCard,
  WIP_LIMIT,
} from './board'
import { CardDialog, ConfirmDialog } from './Dialogs'
import { type DragView, useCardDrag } from './useCardDrag'

const EMPTY_INPUT: CardInput = { title: '', description: '', due: '', priority: 'medium' }
const columnTitle = (id: ColumnId) => COLUMNS.find((c) => c.id === id)!.title

const PRIORITY_STYLE: Record<Priority, string> = {
  low: 'bg-emerald-100 text-emerald-800 ring-emerald-600/20',
  medium: 'bg-amber-100 text-amber-800 ring-amber-600/20',
  high: 'bg-rose-100 text-rose-800 ring-rose-600/20',
}

function formatDate(iso: string) {
  const [y, m, d] = iso.split('-').map(Number)
  return new Date(y, m - 1, d).toLocaleDateString(undefined, { day: 'numeric', month: 'short', year: 'numeric' })
}

type Editing = { mode: 'add'; column: ColumnId } | { mode: 'edit'; id: string } | null

export default function App() {
  const [cards, setCards] = useState<Card[]>(() => loadBoard())
  const [filter, setFilter] = useState<Filter>({ query: '', priority: 'all' })
  const [editing, setEditing] = useState<Editing>(null)
  const [deletingId, setDeletingId] = useState<string | null>(null)
  const [announcement, setAnnouncement] = useState('')
  const [today, setToday] = useState(todayISO)
  const focusAfterRender = useRef<string | null>(null)

  // Persist on every change.
  useEffect(() => {
    saveBoard(cards)
  }, [cards])

  // Keep other tabs in sync, and roll "today" over at midnight.
  useEffect(() => {
    const onStorage = (e: StorageEvent) => {
      if (e.key === STORAGE_KEY) setCards(loadBoard())
    }
    const timer = setInterval(() => setToday(todayISO()), 60_000)
    window.addEventListener('storage', onStorage)
    return () => {
      window.removeEventListener('storage', onStorage)
      clearInterval(timer)
    }
  }, [])

  // Return focus to a card after a keyboard move (it re-mounts in another column).
  useLayoutEffect(() => {
    const id = focusAfterRender.current
    if (!id) return
    focusAfterRender.current = null
    document.querySelector<HTMLElement>(`[data-card-id="${CSS.escape(id)}"]`)?.focus()
  })

  const describePosition = useCallback((list: Card[], id: string) => {
    const card = list.find((c) => c.id === id)
    if (!card) return ''
    const col = list.filter((c) => c.column === card.column)
    return `“${card.title}” moved to ${columnTitle(card.column)}, position ${col.findIndex((c) => c.id === id) + 1} of ${col.length}.`
  }, [])

  const applyMove = useCallback((next: Card[], id: string, refocus: boolean) => {
    setCards(next)
    setAnnouncement(describePosition(next, id))
    if (refocus) focusAfterRender.current = id
  }, [describePosition])

  const { drag, startDrag, suppressClick } = useCardDrag((id, target) => {
    applyMove(moveCard(cards, id, target.column, target.beforeId), id, false)
  })

  const filterActive = isFilterActive(filter)
  const visible = useMemo(() => cards.filter((c) => matchesFilter(c, filter)), [cards, filter])
  const wipExceeded = isWipExceeded(cards)
  const editingCard = editing?.mode === 'edit' ? cards.find((c) => c.id === editing.id) : undefined
  const deletingCard = deletingId ? cards.find((c) => c.id === deletingId) : undefined
  const draggedCard = drag ? cards.find((c) => c.id === drag.id) : undefined

  const handleSave = (input: CardInput) => {
    if (editing?.mode === 'add') {
      const next = addCard(cards, input, editing.column)
      setCards(next)
      setAnnouncement(`Added “${input.title.trim()}” to ${columnTitle(editing.column)}.`)
    } else if (editing?.mode === 'edit') {
      setCards(updateCard(cards, editing.id, input))
      setAnnouncement(`Saved “${input.title.trim()}”.`)
    }
    setEditing(null)
  }

  const handleCardKey = (e: React.KeyboardEvent, card: Card) => {
    if (e.target !== e.currentTarget || !e.shiftKey || e.altKey || e.ctrlKey || e.metaKey) return
    const moves: Record<string, () => Card[]> = {
      ArrowLeft: () => shiftColumn(cards, card.id, -1),
      ArrowRight: () => shiftColumn(cards, card.id, 1),
      ArrowUp: () => shiftWithinColumn(cards, card.id, -1),
      ArrowDown: () => shiftWithinColumn(cards, card.id, 1),
    }
    const fn = moves[e.key]
    if (!fn) return
    e.preventDefault()
    const next = fn()
    if (next !== cards) applyMove(next, card.id, true)
  }

  return (
    <div className="min-h-screen bg-slate-100 text-slate-900">
      <header className="border-b border-slate-200 bg-white">
        <div className="mx-auto flex max-w-7xl flex-wrap items-center gap-3 px-4 py-3">
          <h1 className="mr-auto text-xl font-bold tracking-tight">My Kanban</h1>
          <button
            type="button"
            onClick={() => setEditing({ mode: 'add', column: 'todo' })}
            className="rounded-md bg-indigo-600 px-4 py-2 text-sm font-medium text-white shadow-sm hover:bg-indigo-700 focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600"
          >
            + Add card
          </button>
          <div role="search" className="flex w-full flex-wrap gap-2 sm:w-auto">
            <label className="sr-only" htmlFor="search">Search cards</label>
            <input
              id="search"
              type="search"
              placeholder="Search title or description…"
              value={filter.query}
              onChange={(e) => setFilter((f) => ({ ...f, query: e.target.value }))}
              className="min-w-0 flex-1 rounded-md border border-slate-300 px-3 py-2 text-base sm:w-64 sm:flex-none sm:text-sm"
            />
            <label className="sr-only" htmlFor="priority-filter">Filter by priority</label>
            <select
              id="priority-filter"
              value={filter.priority}
              onChange={(e) => setFilter((f) => ({ ...f, priority: e.target.value as Filter['priority'] }))}
              className="rounded-md border border-slate-300 bg-white px-2 py-2 text-base sm:text-sm"
            >
              <option value="all">All priorities</option>
              {PRIORITIES.map((p) => <option key={p.id} value={p.id}>{p.label}</option>)}
            </select>
          </div>
        </div>
      </header>

      <main className="mx-auto max-w-7xl px-4 py-4">
        <p className="mb-3 hidden text-xs text-slate-500 md:block">
          Tip: drag cards to move them, or focus a card and press <kbd className="rounded border bg-white px-1">Shift</kbd> + arrow keys.
        </p>

        {filterActive && visible.length === 0 && (
          <div role="status" className="mb-4 flex flex-wrap items-center justify-between gap-2 rounded-lg border border-slate-300 bg-white px-4 py-3 text-sm">
            <span>No cards match your search{filter.priority !== 'all' ? ' and priority filter' : ''}.</span>
            <button type="button" onClick={() => setFilter({ query: '', priority: 'all' })} className="font-medium text-indigo-700 hover:underline">
              Clear filters
            </button>
          </div>
        )}

        <div className="grid grid-cols-1 gap-4 md:grid-cols-3">
          {COLUMNS.map((col) => {
            const all = cards.filter((c) => c.column === col.id)
            const shown = visible.filter((c) => c.column === col.id)
            const isDoing = col.id === 'doing'
            const warn = isDoing && wipExceeded
            const isTarget = drag?.target?.column === col.id
            return (
              <section
                key={col.id}
                data-column={col.id}
                aria-labelledby={`col-${col.id}`}
                className={`flex flex-col rounded-xl border p-3 transition-colors ${
                  warn ? 'border-amber-400 bg-amber-50' : 'border-slate-200 bg-slate-200/60'
                } ${isTarget ? 'ring-2 ring-indigo-400' : ''}`}
              >
                <div className="mb-3 flex items-center gap-2">
                  <h2 id={`col-${col.id}`} className="font-semibold">{col.title}</h2>
                  <span
                    data-testid={`count-${col.id}`}
                    aria-label={filterActive ? `${shown.length} of ${all.length} cards shown` : `${all.length} cards`}
                    className={`rounded-full px-2 py-0.5 text-xs font-semibold ${warn ? 'bg-amber-500 text-white' : 'bg-white text-slate-700'}`}
                  >
                    {filterActive ? `${shown.length}/${all.length}` : all.length}
                    {isDoing && !filterActive && <span className="font-normal"> / {WIP_LIMIT}</span>}
                  </span>
                  <button
                    type="button"
                    onClick={() => setEditing({ mode: 'add', column: col.id })}
                    aria-label={`Add card to ${col.title}`}
                    className="ml-auto grid size-8 place-items-center rounded-md text-lg text-slate-600 hover:bg-white"
                  >
                    +
                  </button>
                </div>

                {warn && (
                  <p role="alert" className="mb-3 rounded-md bg-amber-100 px-3 py-2 text-sm text-amber-900">
                    ⚠ Work-in-progress limit exceeded: {all.length} cards in {col.title} (limit {WIP_LIMIT}).
                  </p>
                )}

                <ol className="flex min-h-24 flex-1 flex-col gap-2" aria-label={`${col.title} cards`}>
                  {shown.map((card) => (
                    <li key={card.id} className="contents">
                      {isTarget && drag?.target?.beforeId === card.id && <DropLine />}
                      <CardItem
                        card={card}
                        overdue={isOverdue(card, today)}
                        dragging={drag?.id === card.id}
                        onPointerDown={(e) => startDrag(e, card.id)}
                        onKeyDown={(e) => handleCardKey(e, card)}
                        onEdit={() => !suppressClick.current && setEditing({ mode: 'edit', id: card.id })}
                        onDelete={() => !suppressClick.current && setDeletingId(card.id)}
                        onMoveTo={(to) => applyMove(moveCard(cards, card.id, to, null), card.id, true)}
                      />
                    </li>
                  ))}
                  {isTarget && drag?.target?.beforeId === null && <DropLine />}
                  {shown.length === 0 && (
                    <li className="grid flex-1 place-items-center rounded-lg border-2 border-dashed border-slate-300 px-3 py-6 text-center text-sm text-slate-500">
                      {all.length > 0 ? 'No matching cards' : col.id === 'todo' ? 'Nothing to do yet — add a card' : col.id === 'doing' ? 'Nothing in progress' : 'Nothing done yet'}
                    </li>
                  )}
                </ol>
              </section>
            )
          })}
        </div>
      </main>

      {drag && draggedCard && <DragGhost drag={drag} card={draggedCard} overdue={isOverdue(draggedCard, today)} />}

      <div aria-live="polite" className="sr-only">{announcement}</div>

      <CardDialog
        open={editing !== null && (editing.mode === 'add' || !!editingCard)}
        mode={editing?.mode ?? 'add'}
        initial={editingCard ?? EMPTY_INPUT}
        onSave={handleSave}
        onClose={() => setEditing(null)}
      />
      <ConfirmDialog
        open={!!deletingCard}
        cardTitle={deletingCard?.title ?? ''}
        onClose={() => setDeletingId(null)}
        onConfirm={() => {
          if (deletingCard) {
            setCards(deleteCard(cards, deletingCard.id))
            setAnnouncement(`Deleted “${deletingCard.title}”.`)
          }
          setDeletingId(null)
        }}
      />
    </div>
  )
}

function DropLine() {
  return <div aria-hidden className="h-1 shrink-0 rounded-full bg-indigo-500" data-testid="drop-indicator" />
}

function CardBody({ card, overdue }: { card: Card; overdue: boolean }) {
  return (
    <>
      <div className="flex flex-wrap items-center gap-1.5">
        <span className={`rounded px-1.5 py-0.5 text-xs font-semibold ring-1 ring-inset ${PRIORITY_STYLE[card.priority]}`}>
          {PRIORITIES.find((p) => p.id === card.priority)!.label}
        </span>
        {overdue && <span className="rounded bg-red-600 px-1.5 py-0.5 text-xs font-semibold text-white">Overdue</span>}
      </div>
      <h3 className="mt-1.5 font-medium break-words">{card.title}</h3>
      {card.description && <p className="mt-1 text-sm whitespace-pre-line break-words text-slate-600 line-clamp-4">{card.description}</p>}
      {card.due && (
        <p className={`mt-1.5 text-xs ${overdue ? 'font-semibold text-red-700' : 'text-slate-500'}`}>
          Due <time dateTime={card.due}>{formatDate(card.due)}</time>
        </p>
      )}
    </>
  )
}

function CardItem({ card, overdue, dragging, onPointerDown, onKeyDown, onEdit, onDelete, onMoveTo }: {
  card: Card
  overdue: boolean
  dragging: boolean
  onPointerDown: (e: React.PointerEvent<HTMLElement>) => void
  onKeyDown: (e: React.KeyboardEvent) => void
  onEdit: () => void
  onDelete: () => void
  onMoveTo: (column: ColumnId) => void
}) {
  return (
    <article
      data-card-id={card.id}
      data-overdue={overdue || undefined}
      tabIndex={0}
      aria-label={`${card.title}, ${card.priority} priority${overdue ? ', overdue' : ''}`}
      aria-keyshortcuts="Shift+ArrowLeft Shift+ArrowRight Shift+ArrowUp Shift+ArrowDown"
      onPointerDown={onPointerDown}
      onKeyDown={onKeyDown}
      className={`group relative overflow-hidden rounded-lg border p-3 pl-8 shadow-sm select-none focus-visible:outline-2 focus-visible:outline-offset-2 focus-visible:outline-indigo-600 md:cursor-grab ${
        overdue ? 'border-red-300 bg-red-50' : 'border-slate-200 bg-white'
      } ${dragging ? 'opacity-40' : ''}`}
    >
      {overdue && <span aria-hidden className="absolute inset-y-0 left-0 w-1 bg-red-500" />}
      <span
        data-drag-handle
        aria-hidden
        title="Drag to move"
        className="absolute inset-y-0 left-0 flex w-7 cursor-grab touch-none items-center justify-center text-slate-400"
      >
        <svg width="12" height="20" viewBox="0 0 12 20" fill="currentColor">
          {[3, 10, 17].flatMap((y) => [<circle key={`a${y}`} cx="3" cy={y} r="1.6" />, <circle key={`b${y}`} cx="9" cy={y} r="1.6" />])}
        </svg>
      </span>
      <CardBody card={card} overdue={overdue} />
      <div className="mt-2 flex items-center gap-1 border-t border-slate-100 pt-2">
        <label className="sr-only" htmlFor={`move-${card.id}`}>Move “{card.title}” to column</label>
        <select
          id={`move-${card.id}`}
          value={card.column}
          onChange={(e) => onMoveTo(e.target.value as ColumnId)}
          className="mr-auto min-h-9 rounded border border-slate-200 bg-white px-1.5 text-sm text-slate-700 md:min-h-7 md:text-xs"
        >
          {COLUMNS.map((c) => <option key={c.id} value={c.id}>{c.id === card.column ? `In: ${c.title}` : `Move to ${c.title}`}</option>)}
        </select>
        <button type="button" onClick={onEdit} aria-label={`Edit “${card.title}”`} className="min-h-9 rounded px-3 text-sm font-medium text-slate-600 hover:bg-slate-100 md:min-h-7 md:px-2 md:text-xs">
          Edit
        </button>
        <button type="button" onClick={onDelete} aria-label={`Delete “${card.title}”`} className="min-h-9 rounded px-3 text-sm font-medium text-red-600 hover:bg-red-50 md:min-h-7 md:px-2 md:text-xs">
          Delete
        </button>
      </div>
    </article>
  )
}

function DragGhost({ drag, card, overdue }: { drag: DragView; card: Card; overdue: boolean }) {
  return (
    <div
      aria-hidden
      className={`pointer-events-none fixed top-0 left-0 z-50 rotate-2 rounded-lg border p-3 pl-8 shadow-xl ${overdue ? 'border-red-300 bg-red-50' : 'border-slate-200 bg-white'}`}
      style={{ width: drag.width, transform: `translate(${drag.x - drag.offsetX}px, ${drag.y - drag.offsetY}px) rotate(2deg)` }}
    >
      <CardBody card={card} overdue={overdue} />
    </div>
  )
}

